#include <stdio.h>
#include <string.h>
int main() {
    char s[1005]; if (scanf("%s", s) != 1) return 0;
    int len = strlen(s), first = 1;
    for (int i = len - 1; i >= 0; i--) {
        int d = s[i] - '0';
        if (d % 2 == 0) {
            if (!first) putchar(' ');
            putchar(s[i]);
            first = 0;
        }
    }
    putchar('\n');
    return 0;
}

